document.body.appendChild(renderer.domElement);

// Removed glow texture as requested to match the old distinct point style

// --- Particles ---
const geometry = new THREE.BufferGeometry();
const pPos = new Float32Array(PARTICLE_COUNT * 3);
const pVel = new Float32Array(PARTICLE_COUNT * 3);
const pCol = new Float32Array(PARTICLE_COUNT * 3);
const originalColors = new Float32Array(PARTICLE_COUNT * 3);
const shapeTargets = new Float32Array(PARTICLE_COUNT * 3);

for (let i = 0; i < PARTICLE_COUNT; i++) {
    const r = 1000 * Math.random();
    pPos[i * 3] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 1] = (Math.random() - 0.5) * r;
    pPos[i * 3 + 2] = (Math.random() - 0.5) * r;
    const choice = Math.random();
    let rC, gC, bC;
    if (choice < 0.3) { rC = 0.1; gC = 0.5; bC = 1.0; }
    else if (choice < 0.5) { rC = 0.6; gC = 0.0; bC = 1.0; }
    else if (choice < 0.7) { rC = 1.0; gC = 0.8; bC = 0.2; }
    else { rC = 0.0; gC = 1.0; bC = 0.9; }
    pCol[i * 3] = rC; pCol[i * 3 + 1] = gC; pCol[i * 3 + 2] = bC;
    originalColors[i * 3] = rC; originalColors[i * 3 + 1] = gC; originalColors[i * 3 + 2] = bC;
}

geometry.setAttribute('position', new THREE.BufferAttribute(pPos, 3));
geometry.setAttribute('color', new THREE.BufferAttribute(pCol, 3));
geometry.attributes.position.setUsage(THREE.DynamicDrawUsage);
geometry.attributes.color.setUsage(THREE.DynamicDrawUsage);
geometry.setDrawRange(0, activeParticleCount);

const material = new THREE.PointsMaterial({
    size: 2.0,
    vertexColors: true,
    blending: THREE.AdditiveBlending,
    depthTest: false,
    transparent: true,
    opacity: 0.8
});
const particles = new THREE.Points(geometry, material);
particles.frustumCulled = false;
scene.add(particles);

// --- Starfield ---
const starGeo = new THREE.BufferGeometry();
const STAR_COUNT = 5000;
const sPos = new Float32Array(STAR_COUNT * 3);
const sCol = new Float32Array(STAR_COUNT * 3);
for (let i = 0; i < STAR_COUNT; i++) {
    const r = 2000 + Math.random() * 3000;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    sPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    sPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
    sPos[i * 3 + 2] = r * Math.cos(phi);
    const type = Math.random();
    let c = new THREE.Color();
    if (type > 0.9) c.setHex(0xffaaaa);
    else if (type > 0.7) c.setHex(0xaaccff);
    else c.setHex(0xffffff);
    const b = 0.5 + Math.random() * 0.5;
    sCol[i * 3] = c.r * b; sCol[i * 3 + 1] = c.g * b; sCol[i * 3 + 2] = c.b * b;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(sPos, 3));
starGeo.setAttribute('color', new THREE.BufferAttribute(sCol, 3));
const starMat = new THREE.PointsMaterial({ size: 1.5, vertexColors: true, fog: false, transparent: true, opacity: 0.8 });
const starField = new THREE.Points(starGeo, starMat);
starField.frustumCulled = false;
scene.add(starField);

// --- Helpers ---
const origin = new THREE.Vector3(0, 0, 0);
const singleForceOut = { vx: 0, vy: 0, vz: 0 };
function clamp(v, mn, mx) { return Math.max(mn, Math.min(mx, v)); }
function lerpValue(a, b, t) { return a + (b - a) * t; }
function setActiveParticleTarget(shape) {
    const battleCount = Math.max(BATTLE_PROJECTILE_COUNT * 2 + 512, Math.floor(PARTICLE_COUNT * BATTLE_PARTICLE_SCALE));
    targetActiveParticleCount = (shape === 'battle') ? battleCount : PARTICLE_COUNT;
}
function syncActiveParticleCount() {
    if (activeParticleCount === targetActiveParticleCount) return activeParticleCount;
    const delta = targetActiveParticleCount - activeParticleCount;
    const step = Math.max(96, Math.ceil(Math.abs(delta) * 0.18));
    activeParticleCount += Math.sign(delta) * Math.min(Math.abs(delta), step);
    geometry.setDrawRange(0, activeParticleCount);
    return activeParticleCount;
}


function resetSupernova() { supernova.state = 'IDLE'; supernova.charge = 0; supernova.explosionTime = 0; supernova.epicenter.set(0, 0, 0); }
function resetBattle() {
    battle.p1 = makeFighter('left');
    battle.p2 = makeFighter('right');
    battle.explosions = [];
    battle.roundOver = false;
    battle.roundResetTime = 0;
    battle.winner = null;
}

function getBattleGesture(landmarks, isPinching) {
    if (!landmarks) return isPinching ? 'pinch' : 'none';
    const idxUp = landmarks[8].y < landmarks[5].y;
    const midUp = landmarks[12].y < landmarks[9].y;
    const rngUp = landmarks[16].y < landmarks[13].y;
    const pnkUp = landmarks[20].y < landmarks[17].y;
    
    // Fireball: All 4 fingers clearly extended
    if (idxUp && midUp && rngUp && pnkUp) return 'fireball';
    
    // Volley: Index, Middle, Ring are up (ignoring pinky, much more forgiving)
    if (idxUp && midUp && rngUp && !pnkUp) return 'volley';
    
    // Shield: Index and Middle only
    if (idxUp && midUp && !rngUp && !pnkUp) return 'shield';
    
    if (isPinching) return 'pinch';
    return 'none';
}

function detectShieldGesture(landmarks) {
    return getBattleGesture(landmarks, false) === 'shield';
}

function spawnExplosion(pos, color, power) {
    battle.explosions.push({
        pos: pos.clone(),
        color: color || { r: 1, g: 0.7, b: 0.2 },
        life: 1.0,
        power: power || 1.0,
        radius: 0
    });
    if (battle.explosions.length > 3) battle.explosions.shift();
}

function finishBattleBeam(beam, impactPos, blocked) {
    beam.active = false;
    beam.collided = true;
    beam.blocked = !!blocked;
    beam.recover = 0; // Removed recovery lag completely
    beam.impact.copy(impactPos || beam.head);
}

function isBattleProjectileParticle(i) {
    return (i >> 1) < BATTLE_PROJECTILE_COUNT;
}

function arrowParticleTarget(beam, localIndex, trailLen, out) {
    const t = localIndex / Math.max(1, BATTLE_PROJECTILE_COUNT - 1);
    const seed = Math.sin(localIndex * 12.9898) * 43758.5453;
    const rnd = seed - Math.floor(seed);
    const wobble = Math.sin(localIndex * 0.37 + time * 8) * 0.5 + 0.5;
    const sideX = -beam.dir.y;
    const sideY = beam.dir.x;
    const headPortion = 0.38;
    let along, radius;

    if (t < headPortion) {
        const ht = t / headPortion;
        along = trailLen - ht * BATTLE_ARROW_HEAD;
        radius = ht * 74;
    } else {
        const tt = (t - headPortion) / (1 - headPortion);
        along = trailLen - BATTLE_ARROW_HEAD - tt * (BATTLE_ARROW_LENGTH - BATTLE_ARROW_HEAD);
        radius = 12 + tt * 20;
    }

    along = clamp(along, 0, trailLen + 20);
    const angle = rnd * Math.PI * 2;
    let offset = Math.cos(angle) * radius * (0.35 + wobble * 0.65);
    let zOffset = Math.sin(angle) * radius * 0.45;

    if (beam.type === 'volley') {
        const sub = localIndex % 3;
        if (sub === 1) offset += 60;
        else if (sub === 2) offset -= 60;
    } else if (beam.type === 'fireball') {
        offset *= 2.5;
        zOffset *= 2.5;
    }

    out.x = beam.origin.x + beam.dir.x * along + sideX * offset;
    out.y = beam.origin.y + beam.dir.y * along + sideY * offset;
    out.z = beam.origin.z + beam.dir.z * along + zOffset;
    return out;
}

function fireBattleBeam(fighter, enemy, type) {
    if (fighter.beam.active) return;
    const beam = fighter.beam;
    beam.active = true;
    beam.type = type || 'normal';
    beam.origin.copy(fighter.pos);
    beam.head.copy(fighter.pos);
    beam.target.copy(enemy.pos);
    const dx = enemy.pos.x - fighter.pos.x;
    const dy = enemy.pos.y - fighter.pos.y;
    const dz = enemy.pos.z - fighter.pos.z;
    const len = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
    beam.dir.set(dx / len, dy / len, dz / len);
    
    if (type === 'fireball') {
        beam.speed = BATTLE_PROJECTILE_SPEED * 0.6;
        beam.power = 3.0;
    } else if (type === 'volley') {
        beam.speed = BATTLE_PROJECTILE_SPEED * 1.3;
        beam.power = 1.2;
    } else {
        beam.speed = BATTLE_PROJECTILE_SPEED * (0.7 + fighter.chargeAmount * 0.6);
        beam.power = fighter.chargeAmount > 0.8 ? 2.0 : (fighter.chargeAmount > 0.4 ? 1.5 : 1.0);
    }
    
    beam.life = 0;
    beam.collided = false;
    beam.recover = 0;
    beam.blocked = false;
    beam.impact.copy(fighter.pos);
    fighter.charging = false;
    fighter.chargeAmount = 0;
    kamehamehaCount++;
    addCombo();
    flashHud(fighter.side === 'left' ? '⚡ P1 FIRES!' : '⚡ P2 FIRES!');
}

function updateFighterFromHand(fighter, hand, landmarks) {
    if (!hand.active) {
        fighter.active = false;
        fighter.charging = false;
        fighter.shielding = false;
        fighter.shieldStrength *= 0.82;
        return;
    }
    fighter.active = true;
    fighter.pos.copy(hand.pos);

    const wasCharging = fighter.charging;
    const isPinching = hand.pinch;
    const gesture = getBattleGesture(landmarks, isPinching);

    const isShielding = (gesture === 'shield');
    fighter.shielding = isShielding;
    fighter.shieldStrength += ((isShielding ? 1.0 : 0) - fighter.shieldStrength) * 0.25;

    const isAttacking = (gesture === 'pinch' || gesture === 'volley' || gesture === 'fireball');
    const wasAttacking = fighter.charging;

    if (!fighter.shielding && isAttacking) {
        fighter.charging = true;
        fighter.chargeAmount = Math.min(1, fighter.chargeAmount + (gesture === 'fireball' ? 0.015 : 0.018));
        fighter.pinchLossFrames = 0;
        fighter.lastAttackGesture = gesture;
    } else if (wasAttacking && !isAttacking && !fighter.shielding) {
        fighter.pinchLossFrames = (fighter.pinchLossFrames || 0) + 1;
        if (fighter.pinchLossFrames < 10) {
            fighter.charging = true;
        } else {
            const enemy = (fighter === battle.p1) ? battle.p2 : battle.p1;
            if (enemy.active && fighter.chargeAmount > 0.2) {
                fireBattleBeam(fighter, enemy, fighter.lastAttackGesture);
            } else {
                fighter.chargeAmount = 0;
                fighter.charging = false;
            }
            fighter.pinchLossFrames = 0;
        }
    } else if (!isAttacking) {
        fighter.charging = false;
        fighter.chargeAmount *= 0.92;
        fighter.pinchLossFrames = 0;
    }

    fighter.hitFlash *= 0.9;
}

function updateBeam(fighter, enemy) {
    const beam = fighter.beam;
    if (!beam.active) return;

    beam.life += 0.016;
    beam.head.x += beam.dir.x * beam.speed;
    beam.head.y += beam.dir.y * beam.speed;
    beam.head.z += beam.dir.z * beam.speed;

    if (Math.abs(beam.head.x) > width * 0.5 + BATTLE_DESPAWN_MARGIN ||
        Math.abs(beam.head.y) > height * 0.5 + BATTLE_DESPAWN_MARGIN ||
        beam.life > beam.maxLife) {
        beam.active = false;
        beam.collided = true;
        beam.recover = 0;
        beam.impact.copy(beam.head);
        return;
    }

    if (enemy.active) {
        const dx = beam.head.x - enemy.pos.x;
        const dy = beam.head.y - enemy.pos.y;
        const dz = beam.head.z - enemy.pos.z;
        const hitRadius = (enemy.shielding && enemy.shieldStrength > 0.25) ? BATTLE_SHIELD_RADIUS : BATTLE_HIT_RADIUS;
        if (dx * dx + dy * dy + dz * dz < hitRadius * hitRadius) {
            if (enemy.shielding && enemy.shieldStrength > 0.25) {
                spawnExplosion(beam.head, { r: 0.4, g: 0.8, b: 1.0 }, 0.6);
                finishBattleBeam(beam, beam.head, true);
                flashHud(enemy === battle.p1 ? '🛡️ P1 BLOCKED!' : '🛡️ P2 BLOCKED!');
            } else {
                spawnExplosion(enemy.pos, { r: 1.0, g: 0.4, b: 0.1 }, 1.5 + beam.power);
                finishBattleBeam(beam, enemy.pos, false);
                enemy.hp -= 25 + beam.power * 25;
                enemy.hitFlash = 1.0;
                if (enemy.hp <= 0 && !battle.roundOver) {
                    battle.roundOver = true;
                    battle.winner = (fighter === battle.p1) ? 'P1' : 'P2';
                    battle.roundResetTime = 0;
                    flashHud('🏆 ' + battle.winner + ' WINS!');
                } else {
                    flashHud(enemy === battle.p1 ? '💥 P1 HIT!' : '💥 P2 HIT!');
                }
            }
            beam.active = false;
            beam.collided = true;
            return;
        }
    }

    const otherBeam = enemy.beam;
    if (otherBeam.active) {
        const dx = beam.head.x - otherBeam.head.x;
        const dy = beam.head.y - otherBeam.head.y;
        const dz = beam.head.z - otherBeam.head.z;
        if (dx * dx + dy * dy + dz * dz < BATTLE_HIT_RADIUS * BATTLE_HIT_RADIUS) {
            const midX = (beam.head.x + otherBeam.head.x) * 0.5;
            const midY = (beam.head.y + otherBeam.head.y) * 0.5;
            const midZ = (beam.head.z + otherBeam.head.z) * 0.5;
            const clashPos = new THREE.Vector3(midX, midY, midZ);
            spawnExplosion(clashPos, { r: 1.0, g: 1.0, b: 0.8 }, 0.5); // reduced shake
            flashHud('💥 BEAM CLASH!');
            finishBattleBeam(beam, clashPos, true);
            finishBattleBeam(otherBeam, clashPos, true);
            return;
        }
    }

    if (beam.life > beam.maxLife) beam.active = false;
}

function worldPosFromLandmark(indexTip, target) {
    const vFOV = camera.fov * Math.PI / 180;
    const visibleHeight = 2 * Math.tan(vFOV / 2) * camera.position.z;
    const visibleWidth = visibleHeight * camera.aspect;
    target.set((1 - indexTip.x - 0.5) * visibleWidth, -(indexTip.y - 0.5) * visibleHeight, 0);
}

function updatePrimaryHandState() {
    const primary = hands.left.active ? hands.left : (hands.right.active ? hands.right : null);
    if (primary) {
        indexFingerTip.copy(primary.pos);
        isPinching = primary.pinch;
        lastHandTime = primary.lastSeen;
        handCenter.copy(indexFingerTip);
    } else { isPinching = false; }
}

function chooseSingleHandSide(d) {
    const leftFresh = Date.now() - hands.left.lastSeen < HAND_PERSIST_MS;
    const rightFresh = Date.now() - hands.right.lastSeen < HAND_PERSIST_MS;

    if (leftFresh || rightFresh) {
        const dl = leftFresh ? d.pos.distanceToSquared(hands.left.pos) : Infinity;
        const dr = rightFresh ? d.pos.distanceToSquared(hands.right.pos) : Infinity;
        if (Math.min(dl, dr) < 160000) return dl <= dr ? 'left' : 'right';
    }

    return d.pos.x < 0 ? 'left' : 'right';
}

function applyHandDetection(side, d, now) {
    const targetHand = hands[side];
    // Much snappier lerp so particles feel like they follow the finger instantly
    const lerpFactor = (now - targetHand.lastSeen > 250) ? 0.7 : 0.82;
    const prevX = targetHand.pos.x;
    const prevY = targetHand.pos.y;
    const prevZ = targetHand.pos.z;
    const hadPrevious = targetHand.lastSeen !== 0;
    const dt = Math.max(16, now - targetHand.lastSeen);

    if (targetHand.lastSeen === 0) {
        targetHand.pos.copy(d.pos);
    } else {
        targetHand.pos.lerp(d.pos, lerpFactor);
    }

    if (hadPrevious) {
        targetHand.vel.set(targetHand.pos.x - prevX, targetHand.pos.y - prevY, targetHand.pos.z - prevZ);
        const frameSpeed = targetHand.vel.length() * (16.67 / dt);
        targetHand.speed += (frameSpeed - targetHand.speed) * 0.35;
    } else {
        targetHand.vel.set(0, 0, 0);
        targetHand.speed = 0;
    }

    targetHand.pinch = d.pinch;
    targetHand.active = true;
    targetHand.lastSeen = now;
    lastLandmarks[side] = d.lm;
    pinchDistance = d.pinchDistance;
    lastHandTime = now;
}

function applySingleHandForces(px, py, pz, vx, vy, vz, target) {
    const dx = target.x - px, dy = target.y - py, dz = target.z - pz;
    
    // Core Pull
    const distSq = dx * dx + dy * dy + dz * dz + 100;
    const pull = 2000 / distSq;
    vx += dx * pull * SWARM_FORCE;
    vy += dy * pull * SWARM_FORCE;
    vz += dz * pull * SWARM_FORCE;

    // Anti-Clumping
    const distToFinger = Math.sqrt(dx * dx + dy * dy + dz * dz) + 1;
    if (distToFinger < 150) {
        const push = (150 - distToFinger) * 0.05;
        vx -= (dx / distToFinger) * push;
        vy -= (dy / distToFinger) * push;
        vz -= (dz / distToFinger) * push;
    }

    // Micro-pull
    vx += dx * 0.0002;
    vy += dy * 0.0002;
    vz += dz * 0.0002;

    // Orbital Swirl
    const dist2D = Math.sqrt(dx * dx + dy * dy + 100);
    vx += (dy / dist2D) * 0.5;
    vy -= (dx / dist2D) * 0.5;

    // Boundary Return
    if (px * px + py * py + pz * pz > 500000) {
        vx -= px * 0.0001; vy -= py * 0.0001; vz -= pz * 0.0001;
    }
    
    singleForceOut.vx = vx; singleForceOut.vy = vy; singleForceOut.vz = vz;
    return singleForceOut;
}

function applyDuelHandForces(px, py, pz, vx, vy, vz, hand, otherHand, ownerSign) {
    const targetX = hand.pos.x + ownerSign * DUEL_HAND_OFFSET;
    const targetY = hand.pos.y;
    const targetZ = hand.pos.z;

    const dx = targetX - px, dy = targetY - py, dz = targetZ - pz;
    const distSq = dx * dx + dy * dy + dz * dz + 100;
    
    // Core pull
    const boost = hand.pinch ? PINCH_BOOST_MULTIPLIER : 1.0;
    const pull = (2000 * boost) / distSq;
    vx += dx * pull * SWARM_FORCE;
    vy += dy * pull * SWARM_FORCE;
    vz += dz * pull * SWARM_FORCE;

    // Anti-Clumping
    const distToFinger = Math.sqrt(dx * dx + dy * dy + dz * dz) + 1;
    const coreRadius = hand.pinch ? 50 : 150;
    if (distToFinger < coreRadius) {
        const push = (coreRadius - distToFinger) * (hand.pinch ? 0.08 : 0.05);
        vx -= (dx / distToFinger) * push;
        vy -= (dy / distToFinger) * push;
        vz -= (dz / distToFinger) * push;
    }

    // Micro-pull
    vx += dx * 0.0002;
    vy += dy * 0.0002;
    vz += dz * 0.0002;

    // Orbital Swirl
    const dist2D = Math.sqrt(dx * dx + dy * dy + 100);
    vx += (dy / dist2D) * 0.5;
    vy -= (dx / dist2D) * 0.5;

    // Repel from OTHER hand
    if (otherHand && otherHand.active) {
        const odx = px - otherHand.pos.x, ody = py - otherHand.pos.y, odz = pz - otherHand.pos.z;
        const oDist = Math.sqrt(odx * odx + ody * ody + odz * odz) + 1;
        if (oDist < 150) {
            const repel = (150 - oDist) * 0.02;
            vx += (odx / oDist) * repel;
            vy += (ody / oDist) * repel;
            vz += (odz / oDist) * repel;
        }
    }

    if (px * px + py * py + pz * pz > 500000) {
        vx -= px * 0.0001; vy -= py * 0.0001; vz -= pz * 0.0001;
    }
    
    singleForceOut.vx = vx; singleForceOut.vy = vy; singleForceOut.vz = vz;
    return singleForceOut;
}

function triggerSupernova(positions, colors, midpoint) {
    supernova.state = 'EXPLODING'; supernova.charge = 1; supernova.explosionTime = 0;
    supernova.epicenter.copy(midpoint);
    supernovaCount++; addCombo();
    flashHud('💥 SUPERNOVA');
    for (let i = 0; i < PARTICLE_COUNT; i += 2) {
        const ix = i * 3, iy = ix + 1, iz = ix + 2;
        const rx = positions[ix] - supernova.epicenter.x;
        const ry = positions[iy] - supernova.epicenter.y;
        const rz = positions[iz] - supernova.epicenter.z;
        const distSq = rx * rx + ry * ry + rz * rz + 100;
        const push = (EXPLOSION_FORCE * 400) / distSq;
        pVel[ix] += rx * push;
        pVel[iy] += ry * push;
        pVel[iz] += rz * push;
        colors[ix] = COLOR_FLASH.r; colors[iy] = COLOR_FLASH.g; colors[iz] = COLOR_FLASH.b;
    }
}

// === SHAPES ===
function generateShape(type) {
    const arr = new Float32Array(PARTICLE_COUNT * 3);
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        let x = 0, y = 0, z = 0;
        if (type === 'heart') {
            const t = Math.random() * Math.PI * 2;
            x = 16 * Math.pow(Math.sin(t), 3) * 15;
            y = (13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t)) * 15;
            z = (Math.random() - 0.5) * 100;
        } else if (type === 'saturn') {
            const isRing = Math.random() > 0.4;
            if (isRing) {
                const a = Math.random() * Math.PI * 2, r = 250 + Math.random() * 150;
                x = Math.cos(a) * r; z = Math.sin(a) * r; y = (Math.random() - 0.5) * 10;
            } else {
                const r = 180, theta = Math.random() * Math.PI * 2, phi = Math.acos(2 * Math.random() - 1);
                x = r * Math.sin(phi) * Math.cos(theta);
                y = r * Math.sin(phi) * Math.sin(theta);
                z = r * Math.cos(phi);
            }
            const tilt = 0.4, tx = x;
            x = tx * Math.cos(tilt) - y * Math.sin(tilt);
            y = tx * Math.sin(tilt) + y * Math.cos(tilt);
        } else if (type === 'flower') {
            const k = 4, theta = Math.random() * Math.PI * 2;
            const rc = Math.cos(k * theta), r = 300 * Math.abs(rc) + 50;
            x = r * Math.cos(theta); y = r * Math.sin(theta);
            z = -rc * 100 + (Math.random() - 0.5) * 50;
        } else if (type === 'fireworks') {
            const r = 300 + Math.random() * 300;
            const theta = Math.random() * Math.PI * 2, phi = Math.acos(2 * Math.random() - 1);
            x = r * Math.sin(phi) * Math.cos(theta);
            y = r * Math.sin(phi) * Math.sin(theta);
            z = r * Math.cos(phi);
        }
        arr[i * 3] = x; arr[i * 3 + 1] = y; arr[i * 3 + 2] = z;
    }
    return arr;
}

window.setShape = (shape) => {
    currentShape = shape;
    isSwarmMode = (shape === 'swarm');
    const isDuelMode = (shape === 'duel');
    const isBattleMode = (shape === 'battle' || shape === 'survival');
    isSurvivalMode = (shape === 'survival');
    if (!isDuelMode) resetSupernova();
    if (!isBattleMode) resetBattle();

    const manualPanel = document.getElementById('manual');
    if (manualPanel) manualPanel.classList.remove('open');
    const audioPanel = document.getElementById('audioPanel');
    if (audioPanel) audioPanel.classList.remove('open');

    if (!isSwarmMode && !isDuelMode && !isBattleMode) {
        const targets = generateShape(shape);
        for (let i = 0; i < targets.length; i++) shapeTargets[i] = targets[i];
    }

    document.querySelectorAll('#ui button[data-mode]').forEach(b => b.classList.remove('active'));
    const btn = document.querySelector('#ui button[data-mode="' + shape + '"]');
    if (btn) btn.classList.add('active');

    setActiveParticleTarget(shape);
    for (let i = 0; i < PARTICLE_COUNT * 3; i++) pVel[i] *= 0.1;

    if (isBattleMode) flashHud('⚔ BATTLE MODE');
    if (isDuelMode) flashHud('🔵🔴 DUEL MODE');
};

window.toggleFullscreen = () => {
    if (!document.fullscreenElement) document.documentElement.requestFullscreen();
    else if (document.exitFullscreen) document.exitFullscreen();
};
window.toggleManual = (evt) => {
    if (evt) evt.stopPropagation();
    const panel = document.getElementById('manual');
    if (panel) panel.classList.toggle('open');
};
document.addEventListener('click', (e) => {
    const panel = document.getElementById('manual');
    const manualBtn = document.querySelector('#ui button[data-action="manual"]');
    if (panel && panel.classList.contains('open') && !panel.contains(e.target) && e.target !== manualBtn) {
        panel.classList.remove('open');
    }
    const audioPanel = document.getElementById('audioPanel');
    const musicBtn = document.getElementById('musicBtn');
    if (audioPanel && audioPanel.classList.contains('open') && !audioPanel.contains(e.target) && e.target !== musicBtn) {
        audioPanel.classList.remove('open');
    }
});

// === AUDIO ===
function initAudio() {
    if (audioCtx) return;
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    analyser = audioCtx.createAnalyser();
    analyser.fftSize = 512;
    analyser.smoothingTimeConstant = 0.78;
    audioFreqData = new Uint8Array(analyser.frequencyBinCount);
}

function disconnectAllAudio() {
    if (audioElement) { audioElement.pause(); audioElement.src = ''; audioElement = null; }
    if (audioSourceNode) { try { audioSourceNode.disconnect(); } catch (e) { } audioSourceNode = null; }
    if (micSourceNode) { try { micSourceNode.disconnect(); } catch (e) { } micSourceNode = null; }
    if (micStream) { micStream.getTracks().forEach(t => t.stop()); micStream = null; }
    isMusicPlaying = false; musicReactivityEnabled = false; isMusicLoaded = false;
    audioMode = 'none';
}

window.handleMusicUpload = (input) => {
    const file = input.files[0];
    if (!file) return;
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    audioElement = new Audio();
    audioElement.src = URL.createObjectURL(file);
    audioElement.crossOrigin = 'anonymous';
    audioElement.loop = true;
    audioSourceNode = audioCtx.createMediaElementSource(audioElement);
    audioSourceNode.connect(analyser);
    analyser.connect(audioCtx.destination);
    audioElement.play().catch(e => console.warn('Play blocked:', e));
    isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
    audioMode = 'file';
    updateMusicBtnUI();
    flashHud('🎵 MUSIC LOADED');
    document.getElementById('audioPanel').classList.remove('open');
};

window.loadMusicFromUrl = () => {
    const url = document.getElementById('audioUrl').value.trim();
    if (!url) { alert('Paste a direct .mp3 / .wav / .ogg URL'); return; }
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    audioElement = new Audio();
    audioElement.src = url;
    audioElement.crossOrigin = 'anonymous';
    audioElement.loop = true;
    audioElement.addEventListener('error', () => {
        alert('Could not load that URL.\n\nNote: YouTube/Spotify links DO NOT work due to browser CORS security.\n\nUse:\n• Local MP3 file (Upload button)\n• Direct .mp3 URL from a CORS-enabled host\n• Microphone (sing/play music near mic)');
        flashHud('❌ URL FAILED');
    });
    audioElement.addEventListener('canplay', () => {
        try {
            audioSourceNode = audioCtx.createMediaElementSource(audioElement);
            audioSourceNode.connect(analyser);
            analyser.connect(audioCtx.destination);
            audioElement.play();
            isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
            audioMode = 'file';
            updateMusicBtnUI();
            flashHud('🎵 URL LOADED');
            document.getElementById('audioPanel').classList.remove('open');
        } catch (e) {
            alert('CORS blocked this URL. Use a local file or microphone.');
        }
    });
};

window.useMicrophone = async () => {
    initAudio();
    if (audioCtx.state === 'suspended') audioCtx.resume();
    disconnectAllAudio();
    try {
        micStream = await navigator.mediaDevices.getUserMedia({ audio: true, video: false });
        micSourceNode = audioCtx.createMediaStreamSource(micStream);
        micSourceNode.connect(analyser);
        isMusicLoaded = true; isMusicPlaying = true; musicReactivityEnabled = true;
        audioMode = 'mic';
        updateMusicBtnUI();
        flashHud('🎤 MIC ACTIVE');
        document.getElementById('audioPanel').classList.remove('open');
    } catch (e) {
        alert('Microphone permission denied or unavailable.');
    }
};

window.stopAudio = () => {
    disconnectAllAudio();
    updateMusicBtnUI();
    flashHud('🔇 AUDIO OFF');
    document.getElementById('audioPanel').classList.remove('open');
};

window.toggleMusic = (evt) => {
    if (evt) evt.stopPropagation();
    const panel = document.getElementById('audioPanel');
    if (panel) panel.classList.toggle('open');
};

function updateMusicBtnUI() {
    const btn = document.getElementById('musicBtn');
    if (!btn) return;
    if (audioMode === 'file' && isMusicPlaying) btn.textContent = '♫ Playing';
    else if (audioMode === 'mic') btn.textContent = '🎤 Mic';
    else btn.textContent = '♫ Audio';
    btn.classList.toggle('active', isMusicPlaying);
}

function updateAudioAnalysis() {
    if (!analyser || !musicReactivityEnabled) {
        bassEnergy *= 0.94; midEnergy *= 0.94; trebleEnergy *= 0.94; beatPulse *= 0.9;
        return;
    }
    analyser.getByteFrequencyData(audioFreqData);
    let bass = 0, mid = 0, treb = 0;
    for (let i = 0; i < 8; i++) bass += audioFreqData[i];
    bass /= (8 * 255);
    for (let i = 8; i < 40; i++) mid += audioFreqData[i];
    mid /= (32 * 255);
    for (let i = 40; i < 120; i++) treb += audioFreqData[i];
    treb /= (80 * 255);
    bassEnergy = bass; midEnergy = mid; trebleEnergy = treb;
    if (bass > 0.55 && Date.now() - lastBeatTime > 220) {
        beatPulse = 1.0; lastBeatTime = Date.now();
        beatHitCount++; addCombo();
        shakeAmount = Math.max(shakeAmount, 8);
    }
    beatPulse *= 0.88;
}

// === HUD ===
function addCombo() { comboCount++; comboTimer = 90; }
function updateCombo() { if (comboTimer > 0) comboTimer--; else comboCount = 0; }
function updateHud() {
    const now = performance.now();
    if (!hudElement) hudElement = document.getElementById('hud');
    if (!hudElement || now - hudLastRenderAt < HUD_REFRESH_MS) return;

    let battleStatus = '';
    if (currentShape === 'battle' || currentShape === 'survival') {
        const p1 = battle.p1, p2 = battle.p2;
        const getP1State = () => {
            if (p1.shielding) return '🛡️';
            if (p1.charging) {
                if (p1.lastAttackGesture === 'fireball') return '🔥 CHARGING';
                if (p1.lastAttackGesture === 'volley') return '🏹 VOLLEY';
                const lvl = p1.chargeAmount > 0.8 ? 3 : (p1.chargeAmount > 0.4 ? 2 : 1);
                return `⚡ LVL ${lvl}`;
            }
            return p1.active ? '👤' : '❌';
        };
        const getP2State = () => {
            if (p2.shielding) return '🛡️';
            if (p2.charging) return '⚡ CHARGING';
            return p2.active ? '👤' : '❌';
        };
        
        const ultCharging = (supernova.state === 'CHARGING' && supernova.charge > 0.1) ? 
            `<div class="hud-row" style="color:#ff0; font-weight:bold;">ULTIMATE CHARGING: ${Math.floor(supernova.charge*100)}%</div>` : '';

        battleStatus =
            ultCharging +
            '<div class="hud-battle">' +
            '<div class="hud-fighter">' +
            '<span>P1 ' + getP1State() + '</span>' +
            '<div class="hp-bar"><div class="hp-fill p1" style="width:' + Math.max(0, p1.hp) + '%"></div></div>' +
            '</div>' +
            '<div class="hud-fighter">' +
            '<span>' + (isSurvivalMode ? 'CPU ' : 'P2 ') + getP2State() + '</span>' +
            '<div class="hp-bar"><div class="hp-fill p2" style="width:' + Math.max(0, p2.hp) + '%"></div></div>' +
            '</div>' +
            '</div>';
    }
    const nextHtml =
        '<div class="hud-row"><span>SUPERNOVA</span><b>' + supernovaCount + '</b></div>' +
        '<div class="hud-row"><span>KAMEHAMEHA</span><b>' + kamehamehaCount + '</b></div>' +
        '<div class="hud-row"><span>BEATS</span><b>' + beatHitCount + '</b></div>' +
        battleStatus +
        (comboCount > 1 ? '<div class="hud-combo">x' + comboCount + ' COMBO</div>' : '');

    if (nextHtml !== hudLastHtml) {
        hudElement.innerHTML = nextHtml;
        hudLastHtml = nextHtml;
    }
    hudLastRenderAt = now;
}
function flashHud(text) {
    const el = document.getElementById('hud-flash');
    if (!el) return;
    el.textContent = text;
    el.classList.remove('show');
    void el.offsetWidth;
    el.classList.add('show');
}

// --- MediaPipe ---
const videoElement = document.getElementsByClassName('input_video')[0];

function onResults(results) {
    document.getElementById('loading').style.display = 'none';
    const now = Date.now();

    _detectedHands.length = 0;

    if (results.multiHandLandmarks && results.multiHandLandmarks.length > 0) {
        for (let i = 0; i < results.multiHandLandmarks.length; i++) {
            const lm = results.multiHandLandmarks[i];
            const handednessInfo = results.multiHandedness ? results.multiHandedness[i] : null;
            const handedness = handednessInfo ? handednessInfo.label : ''; // "Left" or "Right" (camera POV)
            const indexTip = lm[8], thumbTip = lm[4];

            const dx = indexTip.x - thumbTip.x, dy = indexTip.y - thumbTip.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            worldPosFromLandmark(indexTip, _tmpHandPos);
            _detectedHands.push({
                lm: lm,
                handedness: handedness,
                pos: _tmpHandPos.clone(),
                pinch: dist < PINCH_THRESHOLD,
                pinchDistance: dist
            });
        }

        if (_detectedHands.length >= 2) {
            // Duel/Battle need two stable players. Assign by actual canvas position so
            // duplicate/flipped MediaPipe labels cannot collapse both hands into one side.
            _detectedHands.sort((a, b) => a.pos.x - b.pos.x);
            applyHandDetection('left', _detectedHands[0], now);
            applyHandDetection('right', _detectedHands[_detectedHands.length - 1], now);
        } else if (_detectedHands.length === 1) {
            const d = _detectedHands[0];
            const side = chooseSingleHandSide(d);
            applyHandDetection(side, d, now);
        }
    }

    // Persistence timeout — only deactivate after HAND_PERSIST_MS of no detection
    if (now - hands.left.lastSeen > HAND_PERSIST_MS) {
        hands.left.active = false; hands.left.pinch = false;
        lastLandmarks.left = null;
    }
    if (now - hands.right.lastSeen > HAND_PERSIST_MS) {
        hands.right.active = false; hands.right.pinch = false;
        lastLandmarks.right = null;
    }

    updatePrimaryHandState();
}

const handTracker = new Hands({ locateFile: (file) => `https://cdn.jsdelivr.net/npm/@mediapipe/hands/${file}` });
// Lower confidence so single extended index finger is reliably detected
handTracker.setOptions({ maxNumHands: 2, modelComplexity: 1, minDetectionConfidence: 0.35, minTrackingConfidence: 0.3 });
handTracker.onResults(onResults);
let isProcessingFrame = false;
const cameraUtils = new Camera(videoElement, {
    onFrame: async () => {
        if (isProcessingFrame) return;
        isProcessingFrame = true;
        try { await handTracker.send({ image: videoElement }); } catch (e) {}
        isProcessingFrame = false;
    },
    width: 640, height: 480
});
cameraUtils.start();

// === BATTLE LOGIC ===
function updateBattleState(hasTwoHands) {
    if (isSurvivalMode) {
        const primaryHand = hands.left.active ? hands.left : (hands.right.active ? hands.right : { active: false });
        const primaryLm = hands.left.active ? lastLandmarks.left : (hands.right.active ? lastLandmarks.right : null);
        updateFighterFromHand(battle.p1, primaryHand, primaryLm);
        
        battle.p2.active = true;
        if (!battle.p2.targetPos) battle.p2.targetPos = new THREE.Vector3();
        if (Math.random() < 0.02) battle.p2.targetPos.set((Math.random() - 0.5) * width * 0.8, (Math.random() - 0.5) * height * 0.8, 0);
        battle.p2.pos.lerp(battle.p2.targetPos, 0.05);

        if (!battle.roundOver && battle.p1.active) {
            if (!battle.p2.charging && Math.random() < 0.01) battle.p2.charging = true;
            if (battle.p2.charging) {
                battle.p2.chargeAmount = Math.min(1, battle.p2.chargeAmount + 0.015);
                if (battle.p2.chargeAmount > 0.6 && Math.random() < 0.05) {
                    const attacks = ['normal', 'volley', 'fireball'];
                    fireBattleBeam(battle.p2, battle.p1, attacks[Math.floor(Math.random()*attacks.length)]);
                }
            } else {
                battle.p2.chargeAmount *= 0.9;
                if (Math.random() < 0.01) battle.p2.shielding = true;
                if (battle.p2.shielding && Math.random() < 0.05) battle.p2.shielding = false;
                battle.p2.shieldStrength += ((battle.p2.shielding ? 1.0 : 0) - battle.p2.shieldStrength) * 0.25;
            }
        }
    } else {
        if (!hasTwoHands) {
            updateFighterFromHand(battle.p1, { active: false }, null);
            updateFighterFromHand(battle.p2, { active: false }, null);
            return;
        }
        updateFighterFromHand(battle.p1, hands.left, lastLandmarks.left);
        updateFighterFromHand(battle.p2, hands.right, lastLandmarks.right);
    }
    
    // ULTIMATE DIAMOND COMBO DETECT (works in both Battle and Survival if you use 2 hands)
    if (isBattleMode && !battle.roundOver && comboCount >= 0 && hands.left.active && hands.right.active) {
        const dx = hands.left.pos.x - hands.right.pos.x;
        const dy = hands.left.pos.y - hands.right.pos.y;
        const distSq = dx * dx + dy * dy;
        const mx = (hands.left.pos.x + hands.right.pos.x) * 0.5;
        const my = (hands.left.pos.y + hands.right.pos.y) * 0.5;

        if (supernova.state !== 'EXPLODING' && supernova.state !== 'COOLDOWN') {
            if (distSq < 15000) {
                triggerSupernova(pPos, originalColors, new THREE.Vector3(mx, my, 0));
                battle.p1.hp = Math.min(100, battle.p1.hp + 20); 
                battle.p2.hp = Math.min(100, battle.p2.hp + 20); 
                comboCount = 0; 
            } else if (distSq < 60000) {
                supernova.state = 'CHARGING';
                supernova.charge = 1 - (Math.sqrt(distSq) / Math.sqrt(60000));
                supernova.epicenter.set(mx, my, 0);
            } else if (supernova.state === 'CHARGING') {
                resetSupernova();
            }
        }
    } else if (isBattleMode && supernova.state === 'CHARGING') {
        resetSupernova();
    }

    updateBeam(battle.p1, battle.p2);
    updateBeam(battle.p2, battle.p1);

    battle.p1.beam.recover = Math.max(0, battle.p1.beam.recover - 0.016);
    battle.p2.beam.recover = Math.max(0, battle.p2.beam.recover - 0.016);

    for (let i = battle.explosions.length - 1; i >= 0; i--) {
        const e = battle.explosions[i];
        e.life -= 0.065; // Decay 3x faster to prevent accumulation lag
        e.radius += 12;
        if (e.life <= 0) battle.explosions.splice(i, 1);
    }

    if (battle.roundOver) {
        battle.roundResetTime += 0.016;
        if (battle.roundResetTime > 3.0) {
            resetBattle();
        }
    }
}

// --- Animation Loop ---
let time = 0;

function animate() {
    requestAnimationFrame(animate);
    time += 0.01;

    updateAudioAnalysis();
    updateCombo();
    updateHud();

    const positions = particles.geometry.attributes.position.array;
    const colors = particles.geometry.attributes.color.array;
    const isDuelMode = currentShape === 'duel';
    const isBattleMode = currentShape === 'battle';
    const hasTwoHands = hands.left.active && hands.right.active;
    const handMotion = hasTwoHands ? clamp((hands.left.speed + hands.right.speed) / 36, 0, 1) : 0;
    const activeCount = syncActiveParticleCount();
    const handIdle = Date.now() - lastHandTime > 1000;

    material.color.setHex(0xffffff);
    // Sizing handled purely by core physics to match old version exactly
    scene.fog.density = 0.0006 + midEnergy * 0.0008;

    if (isSwarmMode && handIdle) {
        indexFingerTip.lerp(origin, 0.05);
        isPinching = false;
    }

    if (isBattleMode) updateBattleState(hasTwoHands);

    // Supernova trigger (duel mode)
    if (isDuelMode && hasTwoHands) {
        const ax = hands.right.pos.x - hands.left.pos.x;
        const ay = hands.right.pos.y - hands.left.pos.y;
        const az = hands.right.pos.z - hands.left.pos.z;
        const distSq = ax * ax + ay * ay + az * az;
        const mx = (hands.left.pos.x + hands.right.pos.x) * 0.5;
        const my = (hands.left.pos.y + hands.right.pos.y) * 0.5;
        const mz = (hands.left.pos.z + hands.right.pos.z) * 0.5;
        if (supernova.state !== 'EXPLODING' && supernova.state !== 'COOLDOWN') {
            if (distSq < SUPERNOVA_DETONATE_DIST * SUPERNOVA_DETONATE_DIST) {
                triggerSupernova(positions, colors, new THREE.Vector3(mx, my, mz));
            } else if (distSq < SUPERNOVA_TRIGGER_DIST * SUPERNOVA_TRIGGER_DIST) {
                const rawDist = Math.sqrt(distSq);
                supernova.state = 'CHARGING';
                supernova.charge = 1 - (rawDist / SUPERNOVA_TRIGGER_DIST);
                supernova.epicenter.set(mx, my, mz);
            } else if (supernova.state === 'CHARGING') resetSupernova();
        }
    } else if (isDuelMode && supernova.state === 'CHARGING') resetSupernova();

    if (supernova.state === 'EXPLODING') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > 0.25) { supernova.state = 'COOLDOWN'; supernova.explosionTime = 0; }
    } else if (supernova.state === 'COOLDOWN') {
        supernova.explosionTime += 0.016;
        if (supernova.explosionTime > COOLDOWN_DURATION) resetSupernova();
    }

    const timeScale = time * 3.0;
    const pulseTable = new Float32Array(100);
    for (let p = 0; p < 100; p++) pulseTable[p] = Math.sin(timeScale + p * 0.3);

    for (let i = 0; i < activeCount; i++) {
        const ix = i * 3, iy = i * 3 + 1, iz = i * 3 + 2;
        let px = positions[ix], py = positions[iy], pz = positions[iz];
        let vx = pVel[ix], vy = pVel[iy], vz = pVel[iz];
        let tr, tg, tb;

        // ===== COLOR =====
        if (isBattleMode) {
            const ownerIsP1 = particleOwner[i] === 0;
            const myFighter = ownerIsP1 ? battle.p1 : battle.p2;
            const isProjectile = isBattleProjectileParticle(i);

            tr = originalColors[ix]; tg = originalColors[iy]; tb = originalColors[iz];
            const sideTint = ownerIsP1 ? {r: 0.44, g: 0.36, b: 1.0} : {r: 0.82, g: 0.28, b: 1.0};

            if (myFighter.active && !myFighter.charging && myFighter.shieldStrength < 0.1 && !myFighter.beam.active) {
                tr = lerpValue(tr, sideTint.r, 0.3);
                tg = lerpValue(tg, sideTint.g, 0.3);
                tb = lerpValue(tb, sideTint.b, 0.3);
            }

            if (myFighter.charging) {
                tr = lerpValue(tr, 1.0, myFighter.chargeAmount * 0.85);
                tg = lerpValue(tg, 1.0, myFighter.chargeAmount * 0.7);
                tb = lerpValue(tb, 0.8, myFighter.chargeAmount * 0.5);
            }

            if (myFighter.beam.active) {
                const beam = myFighter.beam;
                const rx = px - beam.origin.x;
                const ry = py - beam.origin.y;
                const along = rx * beam.dir.x + ry * beam.dir.y;
                const trailLen = Math.sqrt(
                    (beam.head.x - beam.origin.x) ** 2 + (beam.head.y - beam.origin.y) ** 2
                );
                if (along > -30 && along < trailLen + 80) {
                    tr = 1.0; tg = 0.95; tb = 0.6;
                }
            }

            if (isProjectile && myFighter.beam.active) {
                tr = 1.0;
                tg = lerpValue(0.55, 0.98, myFighter.beam.power);
                tb = 0.18;
            } else if (isProjectile && myFighter.beam.recover > 0) {
                const fade = myFighter.beam.recover / BATTLE_ARROW_RECOVER_TIME;
                tr *= fade * 0.25;
                tg *= fade * 0.25;
                tb *= fade * 0.25;
            }

            if (myFighter.shieldStrength > 0.1) {
                tr = lerpValue(tr, 0.4, myFighter.shieldStrength * 0.6);
                tg = lerpValue(tg, 0.9, myFighter.shieldStrength * 0.6);
                tb = lerpValue(tb, 1.0, myFighter.shieldStrength * 0.6);
            }

            if (myFighter.hitFlash > 0.05) {
                tr = lerpValue(tr, 1.0, myFighter.hitFlash);
                tg = lerpValue(tg, 0.1, myFighter.hitFlash);
                tb = lerpValue(tb, 0.1, myFighter.hitFlash);
            }

            // Explosion glow — check only 1-in-8 particles to cut cost
            if ((i & 7) === 0) {
                for (let e = 0; e < battle.explosions.length; e++) {
                    const exp = battle.explosions[e];
                    const dx = px - exp.pos.x;
                    const dy = py - exp.pos.y;
                    const dz = pz - exp.pos.z;
                    const distSq = dx * dx + dy * dy + dz * dz;
                    const radiusSq = (exp.radius + 80) ** 2;
                    if (distSq < radiusSq) {
                        const t = exp.life * 0.8;
                        tr = lerpValue(tr, exp.color.r, t);
                        tg = lerpValue(tg, exp.color.g, t);
                        tb = lerpValue(tb, exp.color.b, t);
                    }
                }
            }
        } else if (isDuelMode && hasTwoHands) {
            const ownerIsLeft = particleOwner[i] === 0;
            const myHand = ownerIsLeft ? hands.left : hands.right;
            const moveGlow = clamp(myHand.speed / 18, 0, 1);
            const corePulse = 0.35 + 0.25 * pulseTable[i % 100];
            const sideTint = ownerIsLeft ? COLOR_POS : COLOR_NEG;
            tr = lerpValue(COLOR_NEBULA.r, sideTint.r, 0.22);
            tg = lerpValue(COLOR_NEBULA.g, sideTint.g, 0.22);
            tb = lerpValue(COLOR_NEBULA.b, sideTint.b, 0.22);
            tr = lerpValue(tr, COLOR_NEBULA_CORE.r, (1 - moveGlow) * corePulse);
            tg = lerpValue(tg, COLOR_NEBULA_CORE.g, (1 - moveGlow) * corePulse);
            tb = lerpValue(tb, COLOR_NEBULA_CORE.b, (1 - moveGlow) * corePulse);
            tr = lerpValue(tr, COLOR_NEBULA.r, moveGlow * 0.55);
            tg = lerpValue(tg, COLOR_NEBULA.g, moveGlow * 0.55);
            tb = lerpValue(tb, COLOR_NEBULA.b, moveGlow * 0.55);
            if (myHand.pinch) {
                tr = lerpValue(tr, 1.0, 0.6);
                tg = lerpValue(tg, 0.8, 0.6);
                tb = lerpValue(tb, 0.0, 0.6);
            }
            if (supernova.state === 'CHARGING') {
                const f = supernova.charge * 0.7;
                tr = lerpValue(tr, COLOR_FLASH.r, f);
                tg = lerpValue(tg, COLOR_FLASH.g, f);
                tb = lerpValue(tb, COLOR_FLASH.b, f);
            } else if (supernova.state === 'EXPLODING') {
                tr = COLOR_FLASH.r; tg = COLOR_FLASH.g; tb = COLOR_FLASH.b;
            } else if (supernova.state === 'COOLDOWN') {
                const cp = supernova.explosionTime / COOLDOWN_DURATION;
                tr = lerpValue(COLOR_FLASH.r, tr, cp);
                tg = lerpValue(COLOR_FLASH.g, tg, cp);
                tb = lerpValue(COLOR_FLASH.b, tb, cp);
            }
        } else if (isDuelMode) {
            tr = originalColors[ix]; tg = originalColors[iy]; tb = originalColors[iz];
        } else if (isPinching) {
            tr = 1.0;
            tg = 0.5 + 0.5 * Math.sin(timeScale + i * 0.005);
            tb = 0.0;
        } else {
            tr = originalColors[ix]; tg = originalColors[iy]; tb = originalColors[iz];
        }

        if (musicReactivityEnabled && trebleEnergy > 0.1) {
            const shimmer = trebleEnergy * 0.3 * Math.sin(timeScale + i * 0.01);
            tr = clamp(tr + shimmer, 0, 1);
            tb = clamp(tb + shimmer * 0.5, 0, 1);
        }

        colors[ix] += (tr - colors[ix]) * 0.12;
        colors[iy] += (tg - colors[iy]) * 0.12;
        colors[iz] += (tb - colors[iz]) * 0.12;

        // ===== PHYSICS =====
        if (isBattleMode) {
            const ownerIsP1 = particleOwner[i] === 0;
            const myFighter = ownerIsP1 ? battle.p1 : battle.p2;
            const enemyFighter = ownerIsP1 ? battle.p2 : battle.p1;
            const isProjectile = isBattleProjectileParticle(i);

            let handled = false;

            // 1) BEAM PARTICLES - arrow projectile, then short impact dissolve.
            if (isProjectile && myFighter.beam.active) {
                const beam = myFighter.beam;
                const trailLen = Math.sqrt(
                    (beam.head.x - beam.origin.x) ** 2 +
                    (beam.head.y - beam.origin.y) ** 2
                );
                const localIndex = i >> 1;
                const target = arrowParticleTarget(beam, localIndex, trailLen, _tmpArrowTarget);
                vx += (target.x - px) * 0.26;
                vy += (target.y - py) * 0.26;
                vz += (target.z - pz) * 0.26;
                vx += beam.dir.x * (5 + beam.power * 7);
                vy += beam.dir.y * (5 + beam.power * 7);
                vz += beam.dir.z * (5 + beam.power * 7);
                handled = true;
            }


            if (!handled) {
                if (myFighter.active) {
                    if (isProjectile) {
                        const dx = myFighter.pos.x - px, dy = myFighter.pos.y - py, dz = myFighter.pos.z - pz;
                        if (dx * dx + dy * dy + dz * dz > 4000) {
                            positions[ix] = myFighter.pos.x + (Math.random() - 0.5) * 40;
                            positions[iy] = myFighter.pos.y + (Math.random() - 0.5) * 40;
                            positions[iz] = myFighter.pos.z + (Math.random() - 0.5) * 40;
                            px = positions[ix]; py = positions[iy]; pz = positions[iz];
                            vx *= 0.1; vy *= 0.1; vz *= 0.1;
                        }
                    }

                    if (myFighter.shieldStrength > 0.05) {
                        const dx = myFighter.pos.x - px, dy = myFighter.pos.y - py, dz = myFighter.pos.z - pz;
                        const dist = Math.sqrt(dx * dx + dy * dy + dz * dz) || 1;
                        const targetR = BATTLE_SHIELD_RADIUS;
                        if (dist > 1) {
                            const force = (dist - targetR) * 0.05 * myFighter.shieldStrength;
                            vx += (dx / dist) * force;
                            vy += (dy / dist) * force;
                            vz += (dz / dist) * force;
                        }
                        const d2D = Math.sqrt(dx * dx + dy * dy + 100);
                        vx += (dy / d2D) * 4 * myFighter.shieldStrength;
                        vy -= (dx / d2D) * 4 * myFighter.shieldStrength;
                    } else {
                        // Apply identical Swarm physics to form the hollow distinct core
                        const r = applySingleHandForces(px, py, pz, vx, vy, vz, myFighter.pos);
                        vx = r.vx; vy = r.vy; vz = r.vz;

                        if (myFighter.charging) {
                            const dx = myFighter.pos.x - px, dy = myFighter.pos.y - py, dz = myFighter.pos.z - pz;
                            const distSq = dx * dx + dy * dy + dz * dz + 100;
                            const boost = (myFighter.chargeAmount * 60000) / distSq;
                            vx += dx * boost; vy += dy * boost; vz += dz * boost;
                        }
                    }
                    handled = true;
                }
            }

            // 5) EXPLOSION blast — push outward, highly optimized
            if ((i & 7) === 0) {
                for (let e = 0; e < battle.explosions.length; e++) {
                    const exp = battle.explosions[e];
                    const dx = px - exp.pos.x;
                    const dy = py - exp.pos.y;
                    const dz = pz - exp.pos.z;
                    const distSq = dx * dx + dy * dy + dz * dz + 100;
                    const radiusSq = (exp.radius + 100) ** 2;
                    if (distSq < radiusSq) {
                        const push = (exp.life * exp.power * 60) / distSq;
                        vx += dx * push;
                        vy += dy * push;
                        vz += dz * push;
                    }
                }
            }

            if (!handled) {
                // No fighters active → orbit loosely in a slow galaxy pattern
                const idleDist = Math.sqrt(px * px + py * py + pz * pz) || 1;
                vx -= (pz / idleDist) * 1.2;
                vz += (px / idleDist) * 1.2;
                if (idleDist > 700) { vx -= px * 0.0006; vy -= py * 0.0006; vz -= pz * 0.0006; }
                else if (idleDist < 180) { vx += px * 0.0012; vz += pz * 0.0012; }
            }
        } else if (isDuelMode) {
            if (supernova.state === 'EXPLODING') {
                // damping handles
            } else if (supernova.state === 'COOLDOWN') {
                vx -= px * 0.002; vy -= py * 0.002; vz -= pz * 0.002;
            } else {
                let target = null;
                let otherTarget = null;
                let ownerSign = 0;
                if (hasTwoHands) {
                    const ownerIsLeft = particleOwner[i] === 0;
                    target = ownerIsLeft ? hands.left : hands.right;
                    otherTarget = ownerIsLeft ? hands.right : hands.left;
                    ownerSign = ownerIsLeft ? -1 : 1;
                }
                if (target) {
                    const r = applyDuelHandForces(px, py, pz, vx, vy, vz, target, otherTarget, ownerSign, i);
                    vx = r.vx; vy = r.vy; vz = r.vz;
                } else {
                    vx -= px * 0.0012; vy -= py * 0.0012; vz -= pz * 0.0012;
                }
            }
        } else if (isSwarmMode) {
            if (handIdle) {
                const distSq = px * px + py * py + pz * pz;
                const dist = Math.sqrt(distSq) || 1;
                const orbitSpeed = 8.0 / Math.pow(dist, 0.4);
                vx -= (pz / dist) * orbitSpeed;
                vz += (px / dist) * orbitSpeed;
                if (Math.abs(py) > 50) vy -= py * 0.005;
                vy += Math.sin(px * 0.01 + timeScale) * 0.4;
                vy += Math.cos(pz * 0.01 + timeScale * 0.8) * 0.4;
                if (dist > 900) {
                    vx -= (px / dist) * 0.2; vy -= (py / dist) * 0.2; vz -= (pz / dist) * 0.2;
                } else if (dist < 200) {
                    vx += (px / dist) * 0.8; vz += (pz / dist) * 0.8;
                }
            } else {
                const r = applySingleHandForces(px, py, pz, vx, vy, vz, indexFingerTip, i);
                vx = r.vx; vy = r.vy; vz = r.vz;
            }
        } else {
            // Shape mode
            const tx = shapeTargets[ix], ty = shapeTargets[iy], tz = shapeTargets[iz];
            const dx = tx - px, dy = ty - py, dz = tz - pz;
            if (musicReactivityEnabled) {
                const sf = SHAPE_FORCE * (1 + bassEnergy * 0.8);
                vx += dx * sf; vy += dy * sf; vz += dz * sf;
                if (beatPulse > 0.3) {
                    const len = Math.sqrt(px * px + py * py + pz * pz) || 1;
                    vx += (px / len) * beatPulse * 4;
                    vy += (py / len) * beatPulse * 4;
                    vz += (pz / len) * beatPulse * 4;
                }
            } else {
                vx += dx * SHAPE_FORCE; vy += dy * SHAPE_FORCE; vz += dz * SHAPE_FORCE;
            }
            const fdx = indexFingerTip.x - px, fdy = indexFingerTip.y - py;
            const fdist = Math.sqrt(fdx * fdx + fdy * fdy);
            if (fdist < 100) { vx -= fdx * 0.1; vy -= fdy * 0.1; }
        }

        if (musicReactivityEnabled) {
            // Push particles toward/around the active hand on beats, not from origin
            // This fixes the mic-inverted bug (loud = particles fly away)
            const beatBoost = beatPulse * 6.5;
            const midWave = Math.sin(timeScale + i * 0.021) * midEnergy * 1.8;
            if (beatBoost > 0.15) {
                // Beat: quick radial pulse from finger tip — particles burst then return
                const refX = indexFingerTip.x, refY = indexFingerTip.y, refZ = indexFingerTip.z;
                const bx = px - refX, by = py - refY, bz = pz - refZ;
                const blen = Math.sqrt(bx * bx + by * by + bz * bz) || 1;
                // Burst outward from finger, damping will pull them back naturally
                vx += (bx / blen) * beatBoost;
                vy += (by / blen) * beatBoost;
                vz += (bz / blen) * beatBoost * 0.5;
            }
            // Mid/treble: shimmer — directional wave perpendicular to direction
            if (midEnergy > 0.06) {
                vx += midWave; vy += Math.cos(timeScale + i * 0.017) * midEnergy * 1.4;
                vz += midWave * 0.6;
            }
            // Bass energy: tighten particles toward finger (opposite of old code)
            if (bassEnergy > 0.12 && audioMode === 'mic') {
                const fdx = indexFingerTip.x - px, fdy = indexFingerTip.y - py;
                const fd = Math.sqrt(fdx * fdx + fdy * fdy) + 1;
                vx += (fdx / fd) * bassEnergy * 3.5;
                vy += (fdy / fd) * bassEnergy * 3.5;
            }
        }

        // Fast pseudo-random jitter without Math.sin/cos
        const seed = (Math.floor(timeScale * 10) + i) % 100;
        const jitter = (seed * 0.0005) - 0.025;
        vx += jitter;
        vy -= jitter * 0.7;
        vz += ((i % 100) * 0.0005) - 0.025;

        // Damping
        vx *= DAMPING; vy *= DAMPING; vz *= DAMPING;

        // Speed clamp
        const speed = Math.sqrt(vx * vx + vy * vy + vz * vz);
        if (speed > MAX_VEL) {
            const s = MAX_VEL / speed;
            vx *= s; vy *= s; vz *= s;
        }

        positions[ix] += vx; positions[iy] += vy; positions[iz] += vz;
        pVel[ix] = vx; pVel[iy] = vy; pVel[iz] = vz;
    }

    particles.geometry.attributes.position.needsUpdate = true;
    particles.geometry.attributes.color.needsUpdate = true;

    // NOTE: Do NOT rotate the scene — it makes hand-tracking coords misalign with particle positions
    scene.rotation.y = 0;

    // Screen shake
    // Remove all screen shake rendering entirely!
    renderer.render(scene, camera);
}

window.addEventListener('resize', () => {
    width = window.innerWidth;
    height = window.innerHeight;
    camera.aspect = width / height;
    camera.updateProjectionMatrix();
    renderer.setSize(width, height);
});

animate();
